  // Sideways shifts tried, in order, when a rotated shape does not fit.
  var KICKS = [0, -1, 1, -2, 2];

  // Locking rule.
  var LOCK_DELAY = 2;      // gravity ticks a piece may spend unable to fall
  var MAX_LOCK_RESETS = 3; // times a piece may restart its lock delay

  // Scoring rule. Points for a clear depend on how many rows go at once, times
  // the current level. The table grows faster than the row count, so clearing
  // rows together always beats clearing the same rows one at a time.
  var CLEAR_POINTS = [0, 100, 300, 500, 800];
  var SOFT_DROP_POINTS = 1; // per cell moved down by the player
  var HARD_DROP_POINTS = 2; // per cell dropped

  // ---- State ----
  var board;       // ROWS x COLS array of piece letters or null
  var current;     // { type, row, col, rot, shape, lockTicks, lockResets } or null
  var queue;       // upcoming piece letters, soonest first
  var bag;         // 7-bag for the random generator
  var score, level, lines, status;
  var timer = null;

  function emptyBoard() {
    var b = [];
    for (var r = 0; r < ROWS; r++) {
      var row = [];
      for (var c = 0; c < COLS; c++) row.push(null);
      b.push(row);
    }
    return b;
  }

  function randomPiece() {
    if (!bag || bag.length === 0) {
      bag = TYPES.slice();
      for (var i = bag.length - 1; i > 0; i--) {
        var j = Math.floor(Math.random() * (i + 1));
        var t = bag[i]; bag[i] = bag[j]; bag[j] = t;
      }
    }
    return bag.pop();
  }

  function sanitizeQueue(q) {
    if (!Array.isArray(q)) return [];
    return q.map(function (x) { return String(x).toUpperCase(); })
            .filter(function (x) { return TYPES.indexOf(x) !== -1; });
  }

  // Keep enough upcoming pieces to fill the preview.
  var PREVIEW_COUNT = 3;
  function fillQueue() {
    while (queue.length < PREVIEW_COUNT) queue.push(randomPiece());
  }

  function pieceCells(p, dRow, dCol) {
    var out = [];
    for (var i = 0; i < p.shape.length; i++) {
      out.push([p.row + p.shape[i][0] + (dRow || 0), p.col + p.shape[i][1] + (dCol || 0)]);
    }
    return out;
  }

  function fits(p, dRow, dCol) {
    var cells = pieceCells(p, dRow, dCol);
    for (var i = 0; i < cells.length; i++) {
      var r = cells[i][0], c = cells[i][1];
      if (c < 0 || c >= COLS || r >= ROWS) return false;
      if (r >= 0 && board[r][c]) return false;
    }
    return true;
  }

  function spawn() {
    fillQueue();
    var type = queue.shift();
    fillQueue();
    var p = {
      type: type, row: 0, col: SPAWN_COL[type], rot: 0, shape: SHAPES[type],
      lockTicks: 0, lockResets: 0
    };
    if (!fits(p, 0, 0)) {
      current = null;
      status = "gameover";
      stopTimer();
      return;
    }
    current = p;
  }

  function lock() {
    var cells = pieceCells(current, 0, 0);
    for (var i = 0; i < cells.length; i++) {
      var r = cells[i][0], c = cells[i][1];
      if (r >= 0 && r < ROWS && c >= 0 && c < COLS) board[r][c] = current.type;
    }
    current = null;
    clearLines();
    spawn();
  }

  // Remove every full row; everything above drops down to fill the gap.
  function clearLines() {
    var kept = board.filter(function (row) {
      return row.some(function (v) { return !v; });
    });
    var cleared = ROWS - kept.length;
    if (cleared === 0) return;
    while (kept.length < ROWS) kept.unshift(emptyBoard()[0]);
    board = kept;
    lines += cleared;
    score += CLEAR_POINTS[cleared] * level;
  }

  // One gravity step. The real timer, tick() and soft drop all run this.
  // If the piece cannot fall, the step counts one tick of lock delay instead.
  // Returns true if the piece moved down.
  function gravityStep() {
    if (status !== "running" || !current) return false;
    if (fits(current, 1, 0)) {
      current.row += 1;
      current.lockTicks = 0;
      return true;
    }
    current.lockTicks += 1;
    if (current.lockTicks >= LOCK_DELAY) lock();
    return false;
  }

  function softDrop() {
    if (gravityStep()) score += SOFT_DROP_POINTS;
  }

  // A sideways move while resting restarts the lock delay, up to
  // MAX_LOCK_RESETS times per piece.
  function move(dCol) {
    if (status !== "running" || !current) return;
    if (!fits(current, 0, dCol)) return;
    var resting = !fits(current, 1, 0);
    current.col += dCol;
    if (resting && current.lockResets < MAX_LOCK_RESETS) {
      current.lockResets += 1;
      current.lockTicks = 0;
    }
  }

  function rotatedShape(p) {
    var rot = (p.rot + 1) % 4;
    if (p.type === "I") return { rot: rot, shape: I_STATES[rot] };
    var size = p.type === "O" ? 2 : 3;
    return {
      rot: rot,
      shape: p.shape.map(function (off) { return [off[1], size - 1 - off[0]]; })
    };
  }

  // Rotate clockwise. If the turned shape does not fit, try shifting it
  // sideways; if nothing fits, leave the piece exactly as it was.
  function rotateCW() {
    if (status !== "running" || !current) return;
    var next = rotatedShape(current);
    var trial = { row: current.row, col: current.col, shape: next.shape };
    for (var i = 0; i < KICKS.length; i++) {
      if (fits(trial, 0, KICKS[i])) {
        current.col += KICKS[i];
        current.rot = next.rot;
        current.shape = next.shape;
        return;
      }
    }
  }

  function hardDrop() {
    if (status !== "running" || !current) return;
    while (fits(current, 1, 0)) {
      current.row += 1;
      score += HARD_DROP_POINTS;
    }
    lock();
  }

  var ACTIONS = {
  }

  // ---- Keyboard ----
  var KEYS = {
    ArrowLeft: "left",
    ArrowRight: "right",
    ArrowUp: "rotateCW",
    x: "rotateCW",
    X: "rotateCW",
    ArrowDown: "softDrop",
    " ": "hardDrop",
    Spacebar: "hardDrop"
  };

  document.addEventListener("keydown", function (e) {
    if (status === "gameover" && e.key === "Enter") {
      e.preventDefault();
      newGame();
      return;
    }
    var action = KEYS[e.key];
    if (!action) return;
    e.preventDefault();
    ACTIONS[action]();
    render();
  });

  document.getElementById("restart").addEventListener("click", function () {
    newGame();
  });

  // ---- Test control surface ----
  window.__tetris = {
    newGame: function (q) { newGame(q); },
    setQueue: function (q) {
      queue = sanitizeQueue(q);
      fillQueue();
      render();
    },
    setBoard: function (rows) {
      board = parseRows(rows);
      render();
    },
    tick: function (n) {
      var count = n === undefined ? 1 : Math.max(0, Math.floor(Number(n)) || 0);
      for (var i = 0; i < count; i++) gravityStep();
      render();
    },
    input: function (action) {
      var fn = ACTIONS[action];
      if (!fn) return;
      fn();
      render();
    },
    getBoard: function () { return boardToRows(); },
    getState: function () {
      return {
        current: current ? { type: current.type, cells: pieceCells(current, 0, 0) } : null,
        next: queue.slice(),
        score: score,
        level: level,
        lines: lines,
        status: status
      };
    }
  };

  newGame();
})();
